#!/usr/bin/env python3
from __future__ import annotations
import base64
import gzip
import subprocess
import sys
from pathlib import Path

PATCH_GZIP_B64 = """"""

ALLOWED = {
    "app/build.gradle",
    "app/src/main/java/com/xspaceart/radar30/AppStateStore.java",
    "app/src/main/java/com/xspaceart/radar30/OverlayController.java",
    "app/src/main/java/com/xspaceart/radar30/ScreenCaptureService.java",
    "app/src/main/java/com/xspaceart/radar30/StandaloneActivity.java",
}

def main() -> int:
    if len(sys.argv) != 2:
        raise SystemExit("usage: apply_v083_project.py <project-root>")
    root = Path(sys.argv[1]).resolve()
    patch = gzip.decompress(base64.b64decode(PATCH_GZIP_B64)).decode("utf-8")
    touched = set()
    for line in patch.splitlines():
        if line.startswith("+++ b/"):
            touched.add(line[6:].split("\t", 1)[0])
    if touched != ALLOWED:
        raise SystemExit(f"unexpected patch paths: {sorted(touched)}")
    proc = subprocess.run(
        ["patch", "-p1", "--forward", "--batch"],
        cwd=root, input=patch, text=True, capture_output=True
    )
    sys.stdout.write(proc.stdout)
    sys.stderr.write(proc.stderr)
    if proc.returncode != 0:
        raise SystemExit(proc.returncode)
    print("V083_CAPTURE_INTEGRITY_PATCH=APPLIED")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
